import{_ as d,C as o,o as s,c as l,j as n,a as t,E as r,a2 as g}from"./chunks/framework.CtQGab4e.js";const z=JSON.parse('{"title":"Kozijnen invoeren","description":"","frontmatter":{},"headers":[],"relativePath":"plattegrond/kozijnen.md","filePath":"plattegrond/kozijnen.md"}'),m={name:"plattegrond/kozijnen.md"};function p(k,e,h,u,c,j){const a=o("Icon"),i=o("Media");return s(),l("div",null,[e[4]||(e[4]=n("h1",{id:"kozijnen-invoeren",tabindex:"-1"},[t("Kozijnen invoeren "),n("a",{class:"header-anchor",href:"#kozijnen-invoeren","aria-label":'Permalink to "Kozijnen invoeren"'},"​")],-1)),e[5]||(e[5]=n("p",null,[t("De kozijnen meet je op locatie, vaak voordat de tekening af is. Je zet ze onder de naam van een constructie, bijvoorbeeld "),n("em",null,"Voorgevel"),t(". Pas na het genereren koppel je ze aan de constructies van het 3D-model, zie "),n("a",{href:"./kozijnen-koppelen.html"},"Kozijnen koppelen"),t(".")],-1)),n("p",null,[e[0]||(e[0]=t("Open ",-1)),r(a,{name:"kozijnen"}),e[1]||(e[1]=t()),e[2]||(e[2]=n("strong",null,"Kozijnen",-1)),e[3]||(e[3]=t(".",-1))]),r(i,{todo:"Afbeelding: het paneel Kozijnen met links de constructies, bovenaan de ruimteknoppen en rechts een tabel met een paar kozijnen."}),e[6]||(e[6]=g('<h2 id="constructies" tabindex="-1">Constructies <a class="header-anchor" href="#constructies" aria-label="Permalink to &quot;Constructies&quot;">​</a></h2><p>Links staat een vaste lijst met namen: gevels, daken, en die van een erker, aanbouw, dakkapel en opbouw. Het getal erachter is het aantal kozijnen. Tik op een naam om zijn kozijnen te zien.</p><p>Past geen enkele naam? Maak er een met <strong>+ Nieuw</strong>. Met ✏️ wijzig je een naam.</p><div class="tip custom-block"><p class="custom-block-title">Gebruik de naam van de constructie in het 3D-model</p><p>Heet een constructie in het 3D-paneel net zo, dan koppelen de kozijnen later vanzelf. Zie <a href="./kozijnen-koppelen.html#vanzelf-gekoppeld">Kozijnen koppelen</a>.</p></div><h2 id="een-kozijn-toevoegen" tabindex="-1">Een kozijn toevoegen <a class="header-anchor" href="#een-kozijn-toevoegen" aria-label="Permalink to &quot;Een kozijn toevoegen&quot;">​</a></h2><ol><li>Kies links de constructie.</li><li>Tik op de ruimte waar het kozijn zit, bijvoorbeeld <strong>wk</strong> (woonkamer) of <strong>slk1</strong>. Er komt bovenaan een rij bij, met de ruimte als omschrijving.</li><li>Vul <strong>L</strong> en <strong>B</strong> in: <strong>m²</strong> rekent zichzelf uit. Of vul alleen de m² in.</li></ol><p>Het glas van een nieuwe rij is het <strong>Standaard glas</strong> (bovenaan). Kies dat dus vóór je begint, als het in de hele woning hetzelfde is.</p><table tabindex="0"><thead><tr><th>Kolom</th><th></th></tr></thead><tbody><tr><td><strong>Glas</strong></td><td>Ook deuren en panelen staan in deze lijst. Bij een deur of paneel komt dat achter de omschrijving.</td></tr><tr><td><strong>Omschrijving</strong></td><td>Vrij.</td></tr><tr><td><strong>L</strong>, <strong>B</strong></td><td>In meters, bijvoorbeeld <code>1,20</code>.</td></tr><tr><td><strong>m²</strong></td><td>Typ je zelf een m², dan worden L en B leeg.</td></tr><tr><td>🌣</td><td><a href="#beschaduwing">Beschaduwing</a>.</td></tr><tr><td>☀</td><td><a href="#zonwering">Zonwering</a>.</td></tr><tr><td>⧉</td><td>Kopie direct eronder.</td></tr><tr><td>✕</td><td>Verwijderen. Dit kan niet ongedaan worden.</td></tr></tbody></table><h3 id="glas-in-een-deur" tabindex="-1">Glas in een deur <a class="header-anchor" href="#glas-in-een-deur" aria-label="Permalink to &quot;Glas in een deur&quot;">​</a></h3><p>Voer de deur in, en direct eronder het glas met <em>glas in deur</em> in de omschrijving. Achter de m² staat dan het percentage glas. Is dat 65% of meer, dan telt het als een glazen deur: <em>&gt;65%</em> komt achter de omschrijving.</p><h2 id="meten-met-de-bosch-meter" tabindex="-1">Meten met de Bosch-meter <a class="header-anchor" href="#meten-met-de-bosch-meter" aria-label="Permalink to &quot;Meten met de Bosch-meter&quot;">​</a></h2><p>Heb je een Bosch GLM50-22, dan komen de maten via Bluetooth vanzelf in de tabel.</p><ol><li>Zet de meter aan, tik bovenaan op <strong>📏 Meter koppelen</strong> en kies de meter.</li><li>Tik in het <strong>m²</strong>-veld van een kozijn.</li><li>Doe een oppervlaktemeting. L, B en m² komen in die rij, en de cursor springt naar de volgende rij zonder m².</li></ol><p>Staat de cursor niet in een m²-veld, dan wordt er niets ingevuld.</p><p><strong>Deur met glas?</strong> Meet eerst de hele deur, met het glas. Doe daarna een min-meting van het glas. De rij wordt de deur zonder glas, en direct eronder komt het glas.</p><h2 id="beschaduwing" tabindex="-1">Beschaduwing <a class="header-anchor" href="#beschaduwing" aria-label="Permalink to &quot;Beschaduwing&quot;">​</a></h2><p>Tik op 🌣 en kies:</p><ul><li><strong>Minimale belemmering</strong> (standaard)</li><li><strong>Constante overstek</strong>: vul het <strong>hoogteverschil</strong> en de <strong>afstand</strong> in, in meters.</li><li><strong>Constante overstek &amp; (zij)belemmering</strong>: ook de <strong>kant</strong> en de <strong>relatieve zijbelemmering</strong>.</li><li><strong>Overige belemmering</strong></li></ul><p>Laat je de maten leeg, dan vul je ze later zelf in Label-wise in.</p><p>Bij deuren en panelen kan geen beschaduwing of zonwering: de knoppen zijn grijs.</p><h2 id="zonwering" tabindex="-1">Zonwering <a class="header-anchor" href="#zonwering" aria-label="Permalink to &quot;Zonwering&quot;">​</a></h2><p>Tik op ☀ en kies de zonwering. Bij een soort met kleurvakjes kies je de kleur.</p>',22))])}const b=d(m,[["render",p]]);export{z as __pageData,b as default};
